begin;
create extension if not exists pgtap with schema extensions;
set local search_path=logos_academy,extensions;
select plan(27);

-- Historical filename retained; 0059 removes v1/v2 by product decision.
select is((select count(*)::integer from curricula where name='Explorer' and version in('v1','v2')),0,'Explorer v1/v2 remain retired');
select is((select count(*)::integer from cycles where curriculum_id in(md5('logos-academy-explorer-v1-curriculum')::uuid,md5('logos-academy-explorer-v2-curriculum')::uuid)),0,'retired cycles are absent');
select is((select count(*)::integer from lesson_templates where id in(select md5('logos-academy-explorer-'||v||'-lesson-'||n)::uuid from unnest(array['v1','v2'])v cross join generate_series(1,16)n)),0,'retired lessons are absent');
select is((select count(*)::integer from activity_templates where id in(select md5('logos-academy-explorer-'||v||'-activity-'||n)::uuid from unnest(array['v1','v2'])v cross join generate_series(1,16)n)),0,'retired activities are absent');
select is((select count(*)::integer from curricula where id=md5('logos-academy-explorer-v3-curriculum')::uuid and status='active' and deleted_at is null),1,'Explorer v3 is active');
select is((select count(*)::integer from cycles where curriculum_id=md5('logos-academy-explorer-v3-curriculum')::uuid and deleted_at is null),4,'current Explorer has four cycles');
select is((select count(*)::integer from lesson_templates l join cycles c on c.tenant_id=l.tenant_id and c.id=l.cycle_id where c.curriculum_id=md5('logos-academy-explorer-v3-curriculum')::uuid and l.deleted_at is null),16,'current Explorer has sixteen lessons');
select is((select count(*)::integer from activity_templates where id in(select md5('logos-academy-explorer-v3-activity-'||n)::uuid from generate_series(1,16)n) and deleted_at is null),16,'current Explorer has sixteen activities');
select results_eq($$select ((c.position-1)*4+l.position)::integer from lesson_templates l join cycles c on c.tenant_id=l.tenant_id and c.id=l.cycle_id where c.curriculum_id=md5('logos-academy-explorer-v3-curriculum')::uuid order by 1$$,$$select n from generate_series(1,16)n$$,'global positions are exactly 1 through 16');
select results_eq($$select ((c.position-1)*4+l.position)::integer from lesson_templates l join cycles c on c.tenant_id=l.tenant_id and c.id=l.cycle_id where c.curriculum_id=md5('logos-academy-explorer-v3-curriculum')::uuid and l.position=4 order by 1$$,$$select position from (values(4),(8),(12),(16)) expected(position) order by position$$,'Project Days are 4, 8, 12 and 16');
select is((select title from lesson_templates where id=md5('logos-academy-explorer-v3-lesson-16')::uuid),'Demo Day: MVP publicado','current Demo Day closes the MVP');
select is((select count(*)::integer from activity_templates where id in(select md5('logos-academy-explorer-v3-activity-'||n)::uuid from generate_series(1,16)n) and length(btrim(title))>0 and length(btrim(context))>0 and length(btrim(objective))>0 and length(btrim(instructions))>0 and jsonb_typeof(steps)='array' and jsonb_array_length(steps)>=5 and length(btrim(continuity_guidance))>0 and length(btrim(plan_b))>0 and length(btrim(reflection_prompt))>0 and length(btrim(portfolio_evidence))>0),16,'all current activities have complete pedagogical fields');
select is((select count(*)::integer from activity_requirements where activity_template_id in(select md5('logos-academy-explorer-v3-activity-'||n)::uuid from generate_series(1,16)n) and deleted_at is null),69,'all current atomic requirements exist');
select is((select count(*)::integer from activity_criteria where activity_template_id in(select md5('logos-academy-explorer-v3-activity-'||n)::uuid from generate_series(1,16)n) and deleted_at is null),64,'all current atomic criteria exist');
select is((select count(*)::integer from activity_templates a where a.id in(select md5('logos-academy-explorer-v3-activity-'||n)::uuid from generate_series(1,16)n) and exists(select 1 from activity_requirements r where r.activity_template_id=a.id and r.is_required and r.deleted_at is null)),16,'every activity requires a concrete artifact');
select is((select count(*)::integer from activity_requirements where activity_template_id in(select md5('logos-academy-explorer-v3-activity-'||n)::uuid from generate_series(1,16)n) and kind not in('text','file','external_link','github_repository')),0,'all deliverable kinds are supported');
select is((select is_required from activity_requirements where id=md5('logos-academy-explorer-v3-requirement-1-4')::uuid),false,'initial repository remains optional');
select is((select count(*)::integer from activity_requirements r where r.activity_template_id in(select md5('logos-academy-explorer-v3-activity-'||n)::uuid from generate_series(1,16)n) and r.deleted_at is null and r.position<>(select count(*) from activity_requirements p where p.activity_template_id=r.activity_template_id and p.deleted_at is null and p.position<=r.position)),0,'current requirement positions are contiguous');
select is((select count(*)::integer from activity_criteria r where r.activity_template_id in(select md5('logos-academy-explorer-v3-activity-'||n)::uuid from generate_series(1,16)n) and r.deleted_at is null and r.position<>(select count(*) from activity_criteria p where p.activity_template_id=r.activity_template_id and p.deleted_at is null and p.position<=r.position)),0,'current criterion positions are contiguous');
select throws_ok($$insert into classes(tenant_id,name,curriculum_id,starts_on,status) values(md5('logos-academy-operational-tenant')::uuid,'Retired v1',md5('logos-academy-explorer-v1-curriculum')::uuid,current_date,'planned')$$,'23514','Explorer v1 no longer accepts new classes or enrollments','purged v1 cannot receive a class');
select throws_ok($$insert into classes(tenant_id,name,curriculum_id,starts_on,status) values(md5('logos-academy-operational-tenant')::uuid,'Retired v2',md5('logos-academy-explorer-v2-curriculum')::uuid,current_date,'planned')$$,'23503',null,'purged v2 cannot receive a class');
select lives_ok($$insert into classes(id,tenant_id,name,curriculum_id,starts_on,status) values(md5('explorer-current-test-class')::uuid,md5('logos-academy-operational-tenant')::uuid,'Current Explorer',md5('logos-academy-explorer-v3-curriculum')::uuid,current_date,'planned')$$,'current Explorer accepts new classes');
select lives_ok($$insert into curricula(id,tenant_id,name,version,status) values(md5('logos-academy-explorer-v3-curriculum')::uuid,md5('logos-academy-operational-tenant')::uuid,'Explorer','v3','active') on conflict do nothing$$,'current import is idempotent');
select is((select count(*)::integer from curricula where id=md5('logos-academy-explorer-v3-curriculum')::uuid),1,'idempotence preserves one current snapshot');
set local role authenticated;
select set_config('request.jwt.claim.sub','b0000000-0000-0000-0000-000000000001',true);
select is((select count(*)::integer from curricula where id=md5('logos-academy-explorer-v3-curriculum')::uuid),0,'tenant B cannot read the operational current curriculum');
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',true);
select is((select count(*)::integer from activity_templates where id=md5('logos-academy-explorer-v3-activity-1')::uuid),0,'student cannot bypass release for current curriculum');
reset role;
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='logos_academy.activity_templates'::regclass),'current activity rows retain enabled and forced RLS');
select * from finish();
rollback;
